@namespace sv_84a71ad032c94009a9a05d01c3e4ee28.Components.Pages.Apply

<div class="step-content">
    <h3>Work History</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="index"
                       ShowRemove="@(Entries.Count > 1)"
                       OnEntryChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
        @if (index < Entries.Count - 1)
        {
            <hr />
        }
    }

    <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
        + Add Another Position
    </button>

    <div class="step-buttons">
        <button type="button" class="btn btn-secondary" @onclick="HandleBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntry>? WorkEntries { get; set; }
    [Parameter] public EventCallback<List<WorkEntry>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<WorkEntry> Entries = new();
    private string? ErrorMessage;

    protected override void OnParametersSet()
    {
        if (WorkEntries is not null && WorkEntries.Count > 0)
        {
            Entries = WorkEntries.Select(e => e).ToList();
        }
        else if (Entries.Count == 0)
        {
            Entries.Add(new WorkEntry(string.Empty, string.Empty, DateTime.Today, null, string.Empty));
        }
    }

    private void UpdateEntry(int index, WorkEntry updated)
    {
        Entries[index] = updated;
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntry(string.Empty, string.Empty, DateTime.Today, null, string.Empty));
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (Entries.Any(e => string.IsNullOrWhiteSpace(e.Company) || string.IsNullOrWhiteSpace(e.Title)))
        {
            ErrorMessage = "Each position must have a company name and job title.";
            return;
        }

        await OnNext.InvokeAsync(Entries.ToList());
    }
}

