toolArgs.file_text:
@namespace sv_84a71ad032c94009a9a05d01c3e4ee28.Components.Pages.Apply

<div class="step-content">
    <h3>Review & Submit</h3>

    @if (IsSubmitted)
    {
        <div class="alert alert-success">
            <h4>Application Submitted!</h4>
            <p>Your application has been successfully submitted. Your application ID is <strong>#@ApplicationId</strong>.</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="alert alert-danger">@ErrorMessage</div>
        }

        <div class="review-section">
            <div class="d-flex justify-content-between align-items-center">
                <h4>Personal Information</h4>
                <button type="button" class="btn btn-sm btn-link" @onclick="() => OnEdit.InvokeAsync(0)">Edit</button>
            </div>
            @if (Personal is not null)
            {
                <dl class="row">
                    <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@Personal.FullName</dd>
                    <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@Personal.Email</dd>
                    <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@Personal.Phone</dd>
                    <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@Personal.Address</dd>
                </dl>
            }
        </div>

        <hr />

        <div class="review-section">
            <div class="d-flex justify-content-between align-items-center">
                <h4>Work History</h4>
                <button type="button" class="btn btn-sm btn-link" @onclick="() => OnEdit.InvokeAsync(1)">Edit</button>
            </div>
            @if (Work is not null)
            {
                @foreach (var entry in Work)
                {
                    <div class="mb-2 ps-3 border-start">
                        <strong>@entry.Title</strong> at @entry.Company<br />
                        <small class="text-muted">
                            @entry.StartDate.ToString("MMM yyyy") – @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                        </small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mb-0 mt-1">@entry.Description</p>
                        }
                    </div>
                }
            }
        </div>

        <hr />

        <div class="review-section">
            <div class="d-flex justify-content-between align-items-center">
                <h4>References</h4>
                <button type="button" class="btn btn-sm btn-link" @onclick="() => OnEdit.InvokeAsync(2)">Edit</button>
            </div>
            @if (References is not null)
            {
                @foreach (var r in References)
                {
                    <div class="mb-2 ps-3 border-start">
                        <strong>@r.Name</strong> (@r.Relationship)<br />
                        <small>@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"• {r.Phone}" : "")</small>
                    </div>
                }
            }
        </div>

        <hr />

        <div class="review-section">
            <div class="d-flex justify-content-between align-items-center">
                <h4>Cover Letter</h4>
                <button type="button" class="btn btn-sm btn-link" @onclick="() => OnEdit.InvokeAsync(3)">Edit</button>
            </div>
            <p class="ps-3" style="white-space: pre-wrap;">@CoverLetter</p>
        </div>

        <hr />

        <div class="step-buttons">
            <button type="button" class="btn btn-secondary" @onclick="HandleBack">Back</button>
            <button type="button" class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @if (IsSubmitting)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                    <span>Submitting...</span>
                }
                else
                {
                    <span>Submit Application</span>
                }
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public List<WorkEntry>? Work { get; set; }
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public EventCallback<int> OnEdit { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int ApplicationId { get; set; }
    [Parameter] public string? ErrorMessage { get; set; }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }

    private async Task HandleSubmit()
    {
        await OnSubmit.InvokeAsync();
    }
}

