@page "/apply"
@using sv_84a71ad032c94009a9a05d01c3e4ee28.Models
@using sv_84a71ad032c94009a9a05d01c3e4ee28.Components.Pages.Apply
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-form-container">
    <h1 class="mb-4">Job Application</h1>

    <StepIndicator CurrentStep="@currentStep"
                   CompletedSteps="@completedSteps"
                   OnStepSelected="GoToStep" />

    <div class="mt-4">
        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep PersonalInfo="@personalInfo"
                                  OnNext="HandlePersonalInfoNext"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync" />
                break;
            case 1:
                <WorkHistoryStep WorkEntries="@workEntries"
                                 OnNext="HandleWorkHistoryNext"
                                 OnBack="GoBack" />
                break;
            case 2:
                <ReferencesStep ExistingReferences="@references"
                                OnNext="HandleReferencesNext"
                                OnBack="GoBack" />
                break;
            case 3:
                <CoverLetterStep ExistingCoverLetter="@coverLetter"
                                 OnNext="HandleCoverLetterNext"
                                 OnBack="GoBack" />
                break;
            case 4:
                <ReviewStep Personal="@personalInfo"
                            Work="@workEntries"
                            References="@references"
                            CoverLetter="@coverLetter"
                            OnEdit="GoToStep"
                            OnBack="GoBack"
                            OnSubmit="HandleSubmit"
                            IsSubmitting="@isSubmitting"
                            IsSubmitted="@isSubmitted"
                            ApplicationId="@applicationId"
                            ErrorMessage="@submitError" />
                break;
        }
    </div>
</div>

@code {
    private int currentStep;
    private HashSet<int> completedSteps = new();

    private PersonalInfo? personalInfo;
    private List<WorkEntry>? workEntries;
    private List<Reference>? references;
    private string? coverLetter;

    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;
    private string? submitError;

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0) currentStep--;
    }

    private void HandlePersonalInfoNext(PersonalInfo info)
    {
        personalInfo = info;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntry> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        submitError = null;
        isSubmitting = true;

        try
        {
            var application = new JobApplication(
                personalInfo!,
                new WorkHistory(workEntries!),
                references!,
                coverLetter ?? string.Empty
            );

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
            completedSteps.Add(4);
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

.application-form-container {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

/* Step Indicator */
.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
    cursor: default;
}

.step-item.completed {
    cursor: pointer;
}

.step-marker {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #6c757d;
}

.step-item.active .step-marker {
    background: #0d6efd;
    border-color: #0d6efd;
    color: #fff;
}

.step-item.completed .step-marker {
    background: #198754;
    border-color: #198754;
    color: #fff;
}

.step-item.dimmed .step-marker {
    background: #f8f9fa;
    border-color: #dee2e6;
    color: #adb5bd;
}

.step-label {
    font-size: 0.8rem;
    text-align: center;
    color: #6c757d;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-item.dimmed .step-label {
    color: #adb5bd;
}

.checkmark {
    font-size: 1.1rem;
}

/* Step content */
.step-content {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 2rem;
}

.step-buttons {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

/* Work entry & reference forms */
.work-entry-form,
.reference-form {
    padding: 1rem;
    border: 1px solid #e9ecef;
    border-radius: 0.375rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.entry-header h4,
.reference-form h5 {
    margin: 0;
}

/* Review section */
.review-section {
    margin-bottom: 0.5rem;
}

.review-section h4 {
    margin-bottom: 0.75rem;
}

