+.step-item.active .step-label {
+    color: #0d6efd;
+    font-weight: 600;
+}
+
+.step-item.completed .step-label {
+    color: #198754;
+}
+
+.step-item.dimmed .step-label {
+    color: #adb5bd;
+}
+
+.checkmark {
+    font-size: 1.1rem;
+}
+
+/* Step content */
+.step-content {
+    background: #fff;
+    border: 1px solid #dee2e6;
+    border-radius: 0.5rem;
+    padding: 2rem;
+}
+
+.step-buttons {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1.5rem;
+    padding-top: 1rem;
+    border-top: 1px solid #eee;
+}
+
+/* Work entry & reference forms */
+.work-entry-form,
+.reference-form {
+    padding: 1rem;
+    border: 1px solid #e9ecef;
+    border-radius: 0.375rem;
+    margin-bottom: 1rem;
+    background: #f8f9fa;
+}
+
+.entry-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 1rem;
+}
+
+.entry-header h4,
+.reference-form h5 {
+    margin: 0;
+}
+
+/* Review section */
+.review-section {
+    margin-bottom: 0.5rem;
+}
+
+.review-section h4 {
+    margin-bottom: 0.75rem;
+}
+

